const L = require('lv-automation').w11;
const rows = $input.all().map((i) => i.json).filter((r) => r.id);
const byBroker = {};
for (const r of rows) (byBroker[r.broker_id] ||= { broker: { id: r.broker_id, contact_person: r.contact_person, whatsapp_number: r.whatsapp_number, email: r.email }, bookings: [] }).bookings.push({ broker_id: r.broker_id, status: r.status, appointment_date: r.appointment_date, method: r.method, lead: { first_name: r.first_name, last_name: r.last_name } });
const out = [];
for (const v of Object.values(byBroker)) { const d = L.digest(v.broker, v.bookings, Date.now()); if (d) out.push({ json: { broker: v.broker, d } }); }
return out;

const REPO = $env.REPO_DIR || '/home/node/repo';
const L = require('lv-automation').w11;
const r = $json; if (!r.id) return { json: { skip: true } };
const lead = { first_name: r.first_name, last_name: r.last_name, phone: r.phone, age_band: r.age_band, budget_band: r.budget_band, bond: r.bond, dependants: r.dependants, work_cover: r.work_cover, call_number: r.lead_call_number, alt_number: r.alt_number, best_time: r.best_time, language: r.language, income_band: r.income_band, conv_state: r.conv_state };
const booking = { id: r.id, appointment_date: r.appointment_date, method: r.method, call_number: r.call_number, join_url: r.join_url, reschedule_count: r.reschedule_count, status: r.status, guest_joining: r.guest_joining === true || r.guest_joining === 't' };
const input = L.briefInput(lead, booking, r.themes || [], { confirmed_t24: !!r.confirmed_at, intro_media_played: !!r.intro_played_at }, r.corpus || []);
const fallback = L.fallbackBrief(lead, booking, input);
const fs = require('fs');
const md = fs.readFileSync(REPO + '/conversation/prompts/precall-brief.md', 'utf8');
const system = (md.split('\u0060\u0060\u0060prompt')[1] || '').split('\u0060\u0060\u0060')[0].trim();
return { json: { skip: false, r, lead, booking, input, fallback, key: L.briefKey(booking), body: { model: 'relay-default', max_tokens: 600, temperature: 0.2, system, messages: [{ role: 'user', content: JSON.stringify(input) }] } } };

const L = require('lv-automation').w11;
const j = $('Brief input (w11.briefInput)').item.json;
let model = null; try { model = JSON.parse((($json.content && $json.content[0] && $json.content[0].text) || '').replace(/\u0060\u0060\u0060json|\u0060\u0060\u0060/g, '').trim()); } catch (e) { model = null; }
const c = L.chooseBrief(model, j.fallback, { last_name: j.lead.last_name });
const vars = L.briefVarsArray(c.brief);
return { json: { ...j, used: c.used, issues: c.issues, wa: { messaging_product: 'whatsapp', to: j.r.whatsapp_number, type: 'template', template: { name: 'precall_brief', language: { code: 'en' }, components: [{ type: 'body', parameters: vars.map((t) => ({ type: 'text', text: t })) }, { type: 'button', sub_type: 'url', index: '0', parameters: [{ type: 'text', text: 'brief/' + j.r.id }] }] } } } };

const L = require('lv-automation').w11;
const r = $json; if (!r.id) return { json: { action: 'none' } };
const d = L.unmarkedSweep(r, { outcome_exists: false, reach: r.reach || null }, Date.now());
return { json: { ...d, r } };

