INSERT INTO public.escalations (brand_id, kind, severity, ref_table, ref_id, lead_id, broker_id, raised_at, note)
SELECT $1::uuid, 'outcome_unmarked', 'normal', 'appointments', $2, $3::uuid, $4::uuid, now(), $5
 WHERE NOT EXISTS (SELECT 1 FROM public.escalations e WHERE e.ref_table = 'appointments' AND e.ref_id = $2 AND e.kind = 'outcome_unmarked');

